// --- Configuration Area ---
var MINIMUM_GB = 6.0;
var RECOMMENDED_GB = 8.0;
var MAXIMUM_GB = 12.0;
// --------------------------

// 1. Critical Minimum Check
if (xmxGB < (MINIMUM_GB * 0.95)) {
    var msg = LanguageProvider.get("custom.memory_below_minimum");
    msg = msg.replace("$XMX$", formattedXmx);
    msg = msg.replace("$MINIMUM$", MINIMUM_GB.toString());
    msg = msg.replace("$RECOMMENDED$", RECOMMENDED_GB.toString());
    var warn = Startup.addBootWarning(msg);
    warn.withMemoryAllocationGuide();
}

// 2. Minimum Recommended Check
else if (xmxGB < (RECOMMENDED_GB * 0.95)) {
    var msg = LanguageProvider.get("custom.memory_below_recommended");
    msg = msg.replace("$XMX$", formattedXmx);
    msg = msg.replace("$RECOMMENDED$", RECOMMENDED_GB.toString());
    var lowMemWarn = Startup.addBootWarning(msg);
    lowMemWarn.withDontShowAgain("low_memory_check");
    lowMemWarn.withMemoryAllocationGuide();
}

// 3. Excessive Allocation Check
// Warning starts exactly when Xmx exceeds MAXIMUM_GB.
if (xmxGB > (MAXIMUM_GB * 1.05)) {
    var msg = LanguageProvider.get("custom.memory_above_maximum");
    msg = msg.replace("$XMX$", formattedXmx);
    msg = msg.replace("$RECOMMENDED$", RECOMMENDED_GB.toString());
    msg = msg.replace("$MAXIMUM$", MAXIMUM_GB.toString());
    var excessiveMemWarn = Startup.addBootWarning(msg);
    excessiveMemWarn.withDontShowAgain("excessive_memory_check");
    excessiveMemWarn.withMemoryAllocationGuide();
}
